import React,{useState} from 'react'; import {createRoot} from 'react-dom/client'; import './styles/app.css';
function Owner(){const [url,setUrl]=useState(localStorage.ownerUrl||''),[token,setToken]=useState(localStorage.ownerToken||''),[data,setData]=useState<any>(),[msg,setMsg]=useState(''); async function call(action:string,payload:any={}){const endpoint=String(url||'').trim().replace(/\/+$/,''); if(!/^https?:\/\//i.test(endpoint))throw new Error('رابط مشروع التراخيص غير صالح'); if(!token.trim())throw new Error('أدخل رمز دخول المدير'); localStorage.ownerUrl=endpoint;localStorage.ownerToken=token; let r:Response; try{r=await fetch(`${endpoint}/functions/v1/${action}`,{method:'POST',headers:{'content-type':'application/json',authorization:`Bearer ${token}`},body:JSON.stringify(payload)});}catch{throw new Error('تعذر الاتصال بمشروع التراخيص')} let j:any;try{j=await r.json()}catch{throw new Error('استجابة الخادم غير صالحة')} if(!r.ok) throw new Error(j.error||'فشل تنفيذ العملية'); return j} async function load(){try{setData(await call('owner-dashboard'));setMsg('')}catch(e:any){setMsg(e.message||'تعذر تحميل البيانات')}} async function createLicense(){const pharmacy_name=prompt('اسم الصيدلية')?.trim()||''; const owner_email=prompt('بريد مالك الصيدلية')?.trim()||''; const license_type=(prompt('نوع الترخيص: ANNUAL للسنوي أو LIFETIME لمدى الحياة','ANNUAL')||'').trim().toUpperCase(); const days=license_type==='ANNUAL'?Number(prompt('مدة الترخيص بالأيام','365')||365):undefined; if(!pharmacy_name||!owner_email||!['ANNUAL','LIFETIME'].includes(license_type))return; try{setMsg(JSON.stringify(await call('owner-control',{operation:'create_license',pharmacy_name,owner_email,owner_name:pharmacy_name,license_type,days}),null,2)); await load()}catch(e:any){setMsg(e.message)}} async function op(operation:string){const license_key=prompt('مفتاح الترخيص')?.trim()||''; if(!license_key)return; try{setMsg(JSON.stringify(await call('owner-control',{operation,license_key}),null,2)); await load()}catch(e:any){setMsg(e.message)}} return <main><h1>لوحة الإدارة المركزية — النجاح لإدارة الصيدليات</h1><div className="card formgrid"><input value={url} onChange={e=>setUrl(e.target.value)} placeholder="رابط مشروع التراخيص" inputMode="url"/><input type="password" value={token} onChange={e=>setToken(e.target.value)} placeholder="رمز دخول المدير"/><button onClick={load}>تحديث البيانات</button><button onClick={createLicense}>إصدار ترخيص</button><button onClick={()=>op('suspend')}>إيقاف الترخيص</button><button onClick={()=>op('revoke')}>إلغاء الترخيص</button><button onClick={()=>op('extend')}>تمديد الاشتراك</button><button onClick={()=>op('unbind_device')}>فك ربط الجهاز</button></div>{msg&&<pre className="card">{msg}</pre>}{data&&<><div className="grid cards">{Object.entries(data.stats||{}).map(([k,v])=><div className="card stat" key={k}><span>{k}</span><b>{String(v)}</b></div>)}</div><div className="card"><h3>التراخيص القريبة من الانتهاء</h3><table><tbody>{data.expiring?.map((l:any)=><tr key={l.license_key}><td>{l.license_key}</td><td>{l.pharmacy_name}</td><td>{l.license_type==='LIFETIME'?'مدى الحياة':l.expires_at}</td><td>{l.status}</td></tr>)}</tbody></table></div><div className="card"><h3>طلبات التفعيل</h3><table><tbody>{data.requests?.map((r:any)=><tr key={`${r.license_key}-${r.device_id}`}><td>{r.license_key}</td><td>{r.device_id}</td><td>{r.status}</td></tr>)}</tbody></table></div></>}</main>}
createRoot(document.getElementById('owner-root')!).render(<React.StrictMode><Owner/></React.StrictMode>);
